mapper.select:
select
,
from cere_shop_product where product_id = #{productId,jdbcType=BIGINT}

SELECT a.shop_id,d.shop_name,d.shop_logo,a.product_id,a.product_name, ifnull(x.users, 0) + a.fictitious_number as users, IF(h.image IS NULL OR h.image='',c.product_image,h.image) image, b.price,b.sku_id,b.price as original_price,IF(f.number IS NULL, a.fictitious_number, f.number + a.fictitious_number) number,b.stock_number from cere_shop_product a LEFT JOIN ( SELECT a.product_id, ANY_VALUE(a.price) as price, ANY_VALUE(a.sku_id) as sku_id, ANY_VALUE(a.price) as original_price, ANY_VALUE(a.stock_number) as stock_number from cere_product_sku a,cere_shop_product b where a.product_id=b.product_id GROUP BY a.product_id ) b ON a.product_id=b.product_id LEFT JOIN ( SELECT a.product_id, ANY_VALUE(a.product_image) as product_image from cere_product_image a,cere_shop_product b where a.product_id=b.product_id GROUP BY a.product_id ) c ON a.product_id=c.product_id LEFT JOIN cere_platform_shop d ON a.shop_id=d.shop_id LEFT JOIN cere_product_classify e ON a.classify_id=e.classify_id LEFT JOIN ( SELECT SUM(number) number, sku_id, ANY_VALUE(order_id) as order_id from cere_order_product GROUP BY sku_id ) f ON b.sku_id=f.sku_id LEFT JOIN cere_shop_order g ON f.order_id=g.order_id and g.state in(2,3,4) LEFT JOIN (SELECT a.sku_id,a.image from cere_sku_name a,cere_product_sku b where a.sku_id=b.sku_id LIMIT 1) h ON b.sku_id=h.sku_id
LEFT JOIN ( SELECT COUNT(a.buyer_user_id) users, a.product_id FROM ( SELECT b.buyer_user_id, a.product_id FROM cere_order_product a, cere_shop_order b where a.order_id = b.order_id
and a.product_id in(
#{productId}
)
GROUP BY a.product_id, b.buyer_user_id ) a GROUP BY a.product_id ) x ON a.product_id = x.product_id
where a.shelve_state=1 and d.state=1
and a.shelve_state=#{shelveState}
and (d.shop_name like concat('%', #{search}, '%') OR a.product_id like concat('%', #{search}, '%') OR a.product_name like concat('%', #{search}, '%'))
and a.classify_id1 = #{classifyId}
and a.classify_id2 = #{classifyId}
and a.classify_id3 = #{classifyId}
and ( a.classify_id1 = #{classifyId} OR a.classify_id2 = #{classifyId} OR a.classify_id3 = #{classifyId} )
and a.product_id in(
#{id}
)
ORDER BY a.create_time DESC

SELECT a.shop_id,d.shop_name,d.shop_logo,a.product_id,a.product_name,a.fictitious_number
from cere_shop_product a
LEFT JOIN cere_platform_shop d ON a.shop_id=d.shop_id
LEFT JOIN cere_product_classify e ON a.classify_id=e.classify_id
where a.shelve_state=1 and d.state=1

    and (d.shop_name like concat('%', #{search}, '%') OR
    a.product_id like concat('%', #{search}, '%') OR
    a.product_name like concat('%', #{search}, '%'))





                and a.classify_id1 = #{classifyId}


                and a.classify_id2 = #{classifyId}


                and a.classify_id3 = #{classifyId}



            and (
            a.classify_id1 = #{classifyId}
            OR a.classify_id2 = #{classifyId}
            OR a.classify_id3 = #{classifyId}
            )




    and a.product_id IN(

        #{id}

    )

ORDER BY a.create_time DESC

select
a.product_id,
ANY_VALUE(ifnull(x.users, 0) + a.fictitious_number) as users
from cere_shop_product a
left join (
select COUNT(a.buyer_user_id) users, a.product_id
from (
select
b.buyer_user_id,
a.product_id
from cere_order_product a, cere_shop_order b
where a.order_id = b.order_id

    and a.product_id in(

        #{id}

    )

group by a.product_id, b.buyer_user_id
) a group by a.product_id
) x on a.product_id = x.product_id
where a.shelve_state = 1

    and a.product_id in(

        #{id}

    )

group by a.product_id

SELECT b.product_id, ANY_VALUE(if(h.image is null OR h.image = '', c.product_image, h.image)) as image, ANY_VALUE(b.price) as price, ANY_VALUE(b.sku_id) as sku_id, ANY_VALUE(b.original_price) as original_price, ANY_VALUE(b.stock_number) as stock_number FROM ( SELECT a.product_id, ANY_VALUE(a.price) as price, ANY_VALUE(a.sku_id) as sku_id, ANY_VALUE(a.price) as original_price, ANY_VALUE(a.stock_number) as stock_number FROM cere_product_sku a, cere_shop_product b WHERE a.product_id = b.product_id GROUP BY a.product_id ) b LEFT JOIN ( SELECT a.product_id, ANY_VALUE(a.product_image) as product_image FROM cere_product_image a, cere_shop_product b WHERE a.product_id = b.product_id GROUP BY a.product_id ) c ON b.product_id = c.product_id LEFT JOIN ( SELECT a.sku_id, a.image FROM cere_sku_name a, cere_product_sku b WHERE a.sku_id = b.sku_id limit 1 ) h ON b.sku_id = h.sku_id
WHERE b.product_id in(
#{id}
)
GROUP BY b.product_id

select b.product_id, ANY_VALUE(if(f.number is null, b.fictitious_number, f.number + b.fictitious_number)) as number from ( select a.product_id, ANY_VALUE(a.price) as price, ANY_VALUE(a.sku_id) as sku_id, ANY_VALUE(a.price) as original_price, ANY_VALUE(a.stock_number) as stock_number, ANY_VALUE(b.fictitious_number) as fictitious_number from cere_product_sku a, cere_shop_product b where a.product_id = b.product_id group by a.product_id ) b left join ( select SUM(number) number, sku_id, ANY_VALUE(order_id) as order_id from cere_order_product group by sku_id ) f on b.sku_id = f.sku_id
where b.product_id in(
#{id}
)
group by b.product_id

SELECT a.shop_id,d.shop_name,a.product_id,a.product_name,c.product_image image, b.price,b.sku_id,b.original_price,a.product_brief,g.users from cere_shop_product a LEFT JOIN (SELECT a.product_id,ANY_VALUE(a.price) as price,ANY_VALUE(a.sku_id) as sku_id,ANY_VALUE(a.price) as original_price from cere_product_sku a,cere_shop_product b where a.product_id=b.product_id GROUP BY a.product_id) b ON a.product_id=b.product_id LEFT JOIN (SELECT a.product_id,ANY_VALUE(a.product_image) as product_image from cere_product_image a,cere_shop_product b where a.product_id=b.product_id GROUP BY a.product_id) c ON a.product_id=c.product_id LEFT JOIN cere_platform_shop d ON a.shop_id=d.shop_id LEFT JOIN (SELECT IF(SUM(number) IS NULL,0,SUM(number)) number,sku_id,ANY_VALUE(order_id) as order_id from cere_order_product GROUP BY sku_id) f ON b.sku_id=f.sku_id LEFT JOIN (SELECT COUNT(a.buyer_user_id) users,a.product_id FROM (SELECT b.buyer_user_id,a.product_id FROM cere_order_product a,cere_shop_order b where a.order_id=b.order_id and b.state in(2,3,4) GROUP BY a.product_id,b.buyer_user_id) a GROUP BY a.product_id) g ON a.product_id=g.product_id where d.state=1 and a.shelve_state=1
and a.classify_id=#{classifyId}
ORDER BY (f.number + a.fictitious_number) DESC LIMIT 4

select ifnull(sum(fictitious_number), 0)
from cere_shop_product
where product_id = #{productId}

SELECT a.shop_id, a.product_id, a.shelve_state, a.if_huabei, b.sku_id, ifnull(g.users, 0) + a.fictitious_number as users, b.price, b.original_price, 0 as activityType from cere_shop_product a LEFT JOIN cere_product_sku b ON a.product_id=b.product_id LEFT JOIN ( SELECT COUNT(a.buyer_user_id) users, a.product_id FROM ( SELECT b.buyer_user_id,a.product_id FROM cere_order_product a, cere_shop_order b where a.order_id = b.order_id and b.state IN(2,3,4) GROUP BY a.product_id, b.buyer_user_id ) a GROUP BY a.product_id ) g ON a.product_id = g.product_id where b.sku_id IN(
#{skuId}
) GROUP BY b.sku_id

SELECT ANY_VALUE(d.shop_id) as shop_id, ANY_VALUE(d.shop_name) as shop_name, ANY_VALUE(d.shop_logo) as shop_logo, a.product_id, ANY_VALUE(b.product_name) as product_name, ANY_VALUE(a.activity_type) as activity_type, ANY_VALUE(IF(a.activity_type = 1, a.activity_id, 0)) as shopGroupWorkId, ANY_VALUE(IF(a.activity_type = 2, a.activity_id, 0)) as shopSeckillId, ANY_VALUE(IF(a.activity_type = 3, a.activity_id, 0)) as shopDiscountId, ANY_VALUE(a.sales_user_count + fictitious_number) as users, ANY_VALUE(c.product_image) as image, ANY_VALUE(a.start_time) as start_time, ANY_VALUE(a.end_time) as end_time, ANY_VALUE(a.state) as state, ANY_VALUE(a.if_enable - 1) as ifEnable, ANY_VALUE(a.enable_time) as enable_time, ANY_VALUE(a.cur_price) as price, ANY_VALUE(a.cur_original_price) as original_price, ANY_VALUE(a.sku_id) as sku_id, ANY_VALUE(n.stock_number) as stock_number,
ANY_VALUE(a.sales_volume) as number
ANY_VALUE(a.product_sales_volume + ifnull(b.fictitious_number,0)) as number
FROM cere_sku_member_real_info a JOIN cere_shop_product b on b.product_id = a.product_id JOIN cere_product_image c on c.product_id = a.product_id JOIN cere_platform_shop d ON b.shop_id = d.shop_id JOIN cere_product_sku n ON a.sku_id = n.sku_id
JOIN cere_product_classify e ON b.classify_id = e.classify_id
where a.member_level_id = #{memberLevelId} and b.shelve_state = 1 and d.state = 1
and a.activity_type = 1
and a.activity_type = 2
and a.activity_type = 3
and b.shop_id = #{shopId}
and (d.shop_name like concat('%', #{search}, '%') OR a.product_id like concat('%', #{search}, '%') OR b.product_name like concat('%', #{search}, '%'))
and b.classify_id1 = #{classifyId}
and b.classify_id2 = #{classifyId}
and b.classify_id3 = #{classifyId}
and ( b.classify_id1 = #{classifyId} OR b.classify_id2 = #{classifyId} OR b.classify_id3 = #{classifyId} )
and a.product_id IN(
#{id}
)
GROUP BY a.product_id ORDER BY ANY_VALUE(a.update_time) DESC, ANY_VALUE(b.update_time) DESC

SELECT d.shop_id, d.shop_name, d.shop_logo, a.product_id, b.product_name, a.activity_type, if(a.activity_type = 1, a.activity_id, 0) as shopGroupWorkId, if(a.activity_type = 2, a.activity_id, 0) as shopSeckillId, if(a.activity_type = 3, a.activity_id, 0) as shopDiscountId, a.sales_user_count + fictitious_number as users, c.product_image as image, a.start_time, a.end_time, a.state, a.if_enable - 1 as ifEnable, a.enable_time, a.cur_price as price, a.cur_original_price original_price, a.sku_id, n.stock_number,
a.sales_volume as number
a.product_sales_volume as number
FROM cere_sku_member_real_info a JOIN cere_shop_product b on b.product_id = a.product_id JOIN cere_product_image c on c.product_id = a.product_id JOIN cere_platform_shop d ON b.shop_id = d.shop_id JOIN cere_product_sku n ON a.sku_id = n.sku_id JOIN cere_recommend_product crp on crp.product_id = a.product_id
and crp.recommend_type = #{recommendType}
JOIN cere_product_classify e ON b.classify_id = e.classify_id
where a.member_level_id = #{memberLevelId} and b.shelve_state = 1 and d.state = 1
and a.activity_type = 1
and a.activity_type = 2
and a.activity_type = 3
and b.shop_id = #{shopId}
and (d.shop_name like concat('%', #{search}, '%') OR a.product_id like concat('%', #{search}, '%') OR b.product_name like concat('%', #{search}, '%'))
and b.classify_id1 = #{classifyId}
and b.classify_id2 = #{classifyId}
and b.classify_id3 = #{classifyId}
and ( b.classify_id1 = #{classifyId} OR b.classify_id2 = #{classifyId} OR b.classify_id3 = #{classifyId} )
and a.product_id IN(
#{id}
)
GROUP BY a.product_id ORDER BY a.update_time DESC, b.update_time DESC
